import{_ as a,c as e,d as r,Z as l}from"./chunks/framework.B0uuYL3Y.js";const p=JSON.parse('{"title":"时间差何时算作侧信道证据","description":"先做同一条件内的比较，再检查观察者能否推断原本受保护的信息。","frontmatter":{"title":"时间差何时算作侧信道证据","description":"先做同一条件内的比较，再检查观察者能否推断原本受保护的信息。","date":"2026-11-25","tags":["微架构安全","侧信道","威胁模型","实验证据"],"book":"microarch-00-intro"},"headers":[],"relativePath":"posts/microarch-04b-observation.md","filePath":"posts/microarch-04b-observation.md"}'),s={name:"posts/microarch-04b-observation.md"};function i(n,t,d,o,h,c){return e(),r("div",null,t[0]||(t[0]=[l('<p><a href="./microarch-04a-measurement.html">访问时间和计数器</a>让我们看到，同一个观测可以同时受到地址翻译、缓存和执行时序影响。侧信道结论还要再前进一步。在已经掌握的公开信息之上，有没有什么原本受保护的信息可以由额外的可观察行为推断？以一个返回通用确认消息的服务为例，把这两个问题分开。</p><nav class="table-of-contents"><ul><li><a href="#先写下谁在什么条件下观察什么">先写下谁在什么条件下观察什么</a></li><li><a href="#只比较汇总时间会在哪里得出错误结论">只比较汇总时间会在哪里得出错误结论</a></li><li><a href="#连接内部状态和外部观测">连接内部状态和外部观测</a></li><li><a href="#参考文献">参考文献</a></li></ul></nav><h2 id="先写下谁在什么条件下观察什么" tabindex="-1">先写下谁在什么条件下观察什么 <a class="header-anchor" href="#先写下谁在什么条件下观察什么" aria-label="Permalink to &quot;先写下谁在什么条件下观察什么&quot;">​</a></h2><p>设服务内部有两种索引结构，使用哪一种由一个业务分类决定，回复本身不透露分类。服务操作者能记录内部事件，远程客户只能看回复和请求耗时。若内部工程师用带权限的 PMU 得到可区分的两组计数，这可以支持内部机制分析。要把结论交给客户的视角，还要证明客户实际能看到的时间保留了差异，且客户能在可比条件下可靠地判断。观察者的能力决定哪条数据是可用证据。</p><table tabindex="0"><thead><tr><th>结论涉及的部分</th><th>本例要回答的问题</th></tr></thead><tbody><tr><td>受保护信息</td><td>分类能否通过正常回复或公开字段直接得知？</td></tr><tr><td>公开条件</td><td>观测者是否已知道网络类型、请求大小或其他分组变量？</td></tr><tr><td>可见观测</td><td>能测端到端时间，还是能在本机观察其他共享资源？</td></tr><tr><td>机制解释</td><td>时间通过哪段活动受到分类影响，其他原因是否也能制造同样结果？</td></tr><tr><td>能否使用</td><td>在包含噪声的实际条件下，判断可靠到什么程度？</td></tr></tbody></table><h2 id="只比较汇总时间会在哪里得出错误结论" tabindex="-1">只比较汇总时间会在哪里得出错误结论 <a class="header-anchor" href="#只比较汇总时间会在哪里得出错误结论" aria-label="Permalink to &quot;只比较汇总时间会在哪里得出错误结论&quot;">​</a></h2><p>下面是一份构造记录。两类业务各 200 次。办公室网络每次用 2 ms，远程网络每次用 30 ms。两类来自办公室网络的比重不同。</p><table tabindex="0"><thead><tr><th>业务分类</th><th style="text-align:right;">办公室网络，2 ms</th><th style="text-align:right;">远程网络，30 ms</th><th style="text-align:right;">直接汇总的中位数</th></tr></thead><tbody><tr><td>A</td><td style="text-align:right;">180</td><td style="text-align:right;">20</td><td style="text-align:right;">2 ms</td></tr><tr><td>B</td><td style="text-align:right;">20</td><td style="text-align:right;">180</td><td style="text-align:right;">30 ms</td></tr></tbody></table><p>粗看中位数相差 28 ms，很容易认为分类被服务执行时间暴露。把记录按观测者已知的网络类型分开，办公室内两类时间都等于 2 ms，远程内都等于 30 ms。在这个例子里，网络类型已经能解释全部时间差。知道网络类型的人再看时间，得不到额外的分类线索。这就是为什么要在<strong>同一公开条件内</strong>比较。</p><p>再改变一个条件。假如在保持网络类型和请求大小都相同的对照组里，A 的响应仍总比 B 多 3 ms，这就值得继续验证。可以先确认计时测到了稳定差异，再检查额外时间发生在等待后端、计算还是访问数据。即使差异确实由程序行为产生，还需对照相关的微架构活动，才能进一步归因到缓存。一个现象可以支持“提供了额外信息”却暂时无法说明“具体由哪一层缓存造成”。</p><h2 id="连接内部状态和外部观测" tabindex="-1">连接内部状态和外部观测 <a class="header-anchor" href="#连接内部状态和外部观测" aria-label="Permalink to &quot;连接内部状态和外部观测&quot;">​</a></h2><p>以缓存为候选解释时，可以把推理压到具体接口。首先说明业务分类怎样改变访问序列。随后解释这些变化怎样影响缓存中的驻留、队列或返回延迟。最后核对这种延迟是否能穿过调度、其他请求和网络噪声，到达给定观察者。对照时保持公开条件相同，并尽量只改变一项机制；遇到不能独立改变的条件，应说明它与别的因素如何耦合。</p><p>换成同核或跨核观察时，同样要给出共享资源及其作用域。<a href="./microarch-01g-false-sharing.html#sharing-transfers">伪共享</a>给出了一个可以复算的例子，两个线程修改的字段不同，仍可能为同一行反复取得写权。若两个任务不共用某一级缓存，可能传递影响的接口还包括一致性、互连或内存系统。报告中的“统计上有差异”“差异可归因于缓存”“观察者可以推断受保护值”分别需要不同的证据。写结论时按所掌握的证据选择措辞。</p><details class="details custom-block"><summary>练习：改变观察者的条件</summary><p>如果前面表格的远程客户不知道网络类型，能直接得到“服务内部存在缓存侧信道”的结论吗？</p><p>时间可能让这个客户推测自己位于哪种网络，进而利用网络与业务分类的相关性。仍缺乏证据说明服务内部是通过缓存制造差异。要区分两种解释，可以在同网络、同请求条件下重新采样，并从服务端核对是否存在支持该机制的事件。观察能力变化会改变隐私判断，机制归因仍需单独证明。</p></details><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li><a href="https://www.intel.com/content/www/us/en/developer/articles/technical/software-security-guidance/best-practices/refined-speculative-execution-terminology.html" target="_blank" rel="noreferrer">Intel 对侧信道与威胁模型的说明</a></li></ul><nav class="article-nav" aria-label="系列文章导航"><p><a href="./microarch-04a-measurement.html" class="article-nav-card article-nav-prev" rel="prev"><span class="article-nav-text"><small>上一篇</small><strong>用计时和计数器分析访存</strong></span></a></p><p><a href="./microarch-06a-shared-cache.html" class="article-nav-card article-nav-next" rel="next"><span class="article-nav-text"><small>下一篇</small><strong>不同的数据为什么会在末级缓存里互相挤掉</strong></span></a></p></nav>',17)]))}const b=a(s,[["render",i]]);export{p as __pageData,b as default};
